/** אחסון בדפדפן — שלושת הסוגים. */
export function leakToBrowserStorage(value: string): void {
  window.localStorage.setItem('canary', value);
  window.sessionStorage.setItem('canary', value);
  window.indexedDB.open('canary');
}
